package com.limitedwalk;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.*;

import javax.inject.Inject;
import java.awt.*;
import java.util.Collection;

public class TileOverlay extends Overlay
{
    private static final int MAX_DRAW_DISTANCE = 32;

    private final Client client;
    private final LimitedWalkPlugin plugin;
    private final LimitedWalkConfig config;

    private Color configOutlineColor;
    private Color configFillColor;
    private Stroke configStroke;

    @Inject
    private TileOverlay(Client client, LimitedWalkPlugin plugin, LimitedWalkConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.LOW);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        final Collection<WorldPoint> points = plugin.getLimitedPoints();
        if (points.isEmpty())
        {
            return null;
        }

        for (final WorldPoint point : points)
        {
            if (point.getPlane() != client.getPlane())
            {
                continue;
            }

            drawTile(graphics, point);
        }

        return null;
    }

    protected void updateConfigs(){
        configOutlineColor = config.tileOutlineColor();
        configFillColor = config.tileFillColor();
        configStroke = new BasicStroke((float) config.borderWidth());
    }

    private void drawTile(Graphics2D graphics, WorldPoint point)
    {
        WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();

        if (point.distanceTo(playerLocation) >= MAX_DRAW_DISTANCE)
        {
            return;
        }

        LocalPoint lp = LocalPoint.fromWorld(client, point);
        if (lp == null)
        {
            return;
        }

        Polygon poly = Perspective.getCanvasTilePoly(client, lp);
        if (poly != null)
        {
            OverlayUtil.renderPolygon(graphics, poly, configOutlineColor, configFillColor, configStroke);
        }
    }
}

